    ]
  },
  {
    "alert_id": "ALERT_EGFR_MONITORING_GAP_003",
    "title": "eGFR not documented despite TDF and renal risk factors",
    "message": "Guidelines require eGFR monitoring before TDF initiation, at 3 and 6 months, then 6–12 monthly, and advise avoiding TDF if eGFR < 50 mL/min/1.73m². Patient has been on TDF for 6 years with hypertension and trace proteinuria, yet no eGFR is recorded today. Creatinine of 112 umol/L alone is insufficient for safe monitoring. High-risk patients with co-existent hypertension warrant closer renal surveillance.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate and document eGFR at this visit. Given hypertension and proteinuria, schedule renal monitoring at least every 6 months.",
