    ]
  },
  {
    "alert_id": "ALERT_BP_CONTROL_GAP_004",
    "title": "Uncontrolled BP with trace proteinuria needs escalation",
    "message": "Guidelines list lower limb oedema as a common amlodipine side effect requiring observation. Patient has BP 146/94 despite amlodipine 5 mg, with admitted non-adherence and trace proteinuria attributed to hypertension. The plan only refills the same dose without escalation or urinalysis follow-up. Persistent hypertension with proteinuria may worsen renal function, compounding TDF nephrotoxicity risk.",
    "issue_type": "plan_review",
    "severity": "moderate",
    "recommended_action": "Address adherence barriers. Consider amlodipine dose increase to 10 mg or add a second antihypertensive. Recheck BP and proteinuria sooner than 6 months.",
